@extends('layouts.admin') @section('title','Giao dịch kho') @section('content')<div class="page-header"><div><h1 class="page-title">Giao dịch kho</h1><p class="page-subtitle">Nhập, xuất, hao hụt và điều chỉnh đều giữ lịch sử.</p></div><a class="btn btn-secondary" href="{{ route('inventory.index') }}">Tồn kho</a></div>@can('inventory.adjust')<form class="panel" method="post" action="{{ route('inventory.transactions.store') }}" style="margin-bottom:18px" data-no-loading>@csrf<div class="form-grid"><div><label class="form-label">Loại giao dịch</label><select class="form-select" name="type"><option value="in">Nhập kho</option><option value="out">Xuất kho</option><option value="adjustment">Điều chỉnh (+/-)</option><option value="waste">Hủy / hỏng</option><option value="return">Hoàn kho</option></select></div><div><label class="form-label">Nhà cung cấp</label><select class="form-select" name="supplier_id"><option value="">Không áp dụng</option>@foreach($suppliers as $supplier)<option value="{{ $supplier->id }}">{{ $supplier->name }}</option>@endforeach</select></div><div class="form-group full"><label class="form-label">Lý do</label><input class="form-control" name="reason" maxlength="500"></div></div><div class="table-wrap" style="margin-top:14px"><table class="data-table"><thead><tr><th>Nguyên liệu</th><th>Số lượng thay đổi</th><th>Đơn giá</th><th></th></tr></thead><tbody id="stock-lines"><tr><td><select class="form-select" name="items[0][inventory_item_id]" required>@foreach($items as $item)<option value="{{ $item->id }}">{{ $item->name }} ({{ $item->unit }})</option>@endforeach</select></td><td><input class="form-control" type="number" step="0.001" name="items[0][quantity]" required></td><td><input class="form-control" type="number" min="0" step="0.01" name="items[0][unit_cost]"></td><td><button class="btn btn-secondary icon-btn remove-line" type="button"><i data-lucide="x"></i></button></td></tr></tbody></table></div><div class="actions" style="margin-top:12px"><button class="btn btn-secondary" type="button" id="add-stock-line"><i data-lucide="plus"></i> Thêm dòng</button><button class="btn btn-primary" type="submit"><i data-lucide="save"></i> Ghi giao dịch</button></div></form>@endcan<div class="table-wrap"><table class="data-table"><thead><tr><th>Mã</th><th>Loại</th><th>Chi tiết</th><th>Lý do</th><th>Thời gian</th></tr></thead><tbody>@forelse($transactions as $transaction)<tr><td class="cell-title">{{ $transaction->transaction_code }}</td><td>{{ $transaction->type->value }}</td><td>@foreach($transaction->items as $line)<div>{{ $line->inventoryItem->name }}: <strong>{{ $line->quantity }}</strong> ({{ $line->before_quantity }} → {{ $line->after_quantity }})</div>@endforeach</td><td>{{ $transaction->reason?:'—' }}</td><td>{{ $transaction->created_at->format('d/m/Y H:i') }}</td></tr>@empty<tr><td colspan="5" class="empty">Chưa có giao dịch kho.</td></tr>@endforelse</tbody></table></div><div class="pagination">{{ $transactions->links() }}</div>@endsection @push('scripts')<script>let lineIndex=1;document.getElementById('add-stock-line')?.addEventListener('click',()=>{const row=document.querySelector('#stock-lines tr').cloneNode(true);row.querySelectorAll('input,select').forEach(el=>{el.name=el.name.replace(/\[0\]/,'['+(lineIndex)+']');if(el.tagName==='INPUT')el.value=''});document.getElementById('stock-lines').append(row);lineIndex++});document.getElementById('stock-lines')?.addEventListener('click',e=>{if(e.target.closest('.remove-line')&&document.querySelectorAll('#stock-lines tr').length>1)e.target.closest('tr').remove()});</script>@endpush
